from test_bufftap import test, tests
import test_nearby
setup=test_nearby.setup
test('Nothing is offered while stealthed, and buffing resumes after',"IsStealthed=function() return true end; refresh(); assert(not BuffTap.action and BuffTap:ReminderPauseReason()=='stealthed'); IsStealthed=function() return false end; refresh(); assert(BuffTap.action)")
test('Nearby holds back while stealthed',setup+"IsStealthed=function() return true end; refresh(); assert(not BuffTap.action); assert(BuffTap:NearbyEntry('nameplate1')==nil)")
test('A missing stealth API never pauses BuffTap',"IsStealthed=nil; refresh(); assert(BuffTap.action and BuffTap:ReminderPauseReason()==nil)")
test('Nearby page has the PvP protection switch, shared with Helpers',"local B=BuffTap; B:Options(); local f=B.options; assert(f.nearbyPvp and f.nearbyPvp:GetChecked()==(B.db.pvpProtection==true)); f.nearbyPvp:SetChecked(false); f.nearbyPvp.scripts.OnClick(f.nearbyPvp); assert(B.db.pvpProtection==false); B:Options(); assert(not B.options.pvpProtection or B.options.pvpProtection:GetChecked()==false)")
test('Nearby all-players view stays listed while stealthed, with buffing paused',setup+"BuffTap.db.nearbyShowAll=true; IsStealthed=function() return true end; refresh(); BuffTap:UpdateNearbyWindow(); local f=BuffTap.nearbyFrame; assert(BuffTap:NearbyBrowsePause()=='stealthed'); assert(f.pauseRow and f.pauseRow.shown and f.pauseRow.text.text:find('Paused: stealthed. Invites still work.',1,true)); assert(not f.rows[1].entry); assert(f.rows[2].entry,'r2'); assert(#f.rows[2].entry.actions==0,'acts'); assert(not f.rows[2].attrs.type1,'type'); IsStealthed=function() return false end; refresh(); BuffTap:UpdateNearbyWindow(); assert(not f.pauseRow.shown,'pr'); assert(f.rows[1].entry,'r1')")
test('Pause row shows alone when the all-players view is off',setup+"BuffTap.db.nearbyShowAll=false; IsStealthed=function() return true end; refresh(); BuffTap:UpdateNearbyWindow(); local f=BuffTap.nearbyFrame; assert(f.pauseRow.shown and f.pauseRow.text.text=='Paused: stealthed' and not f.status.shown)")
test('Resting pause uses the pause row too',setup+"BuffTap.db.nearbyShowAll=true; BuffTap.db.pauseResting=true; BuffTap.db.nearbyWhileResting=false; IsResting=function() return true end; refresh(); BuffTap:UpdateNearbyWindow(); local f=BuffTap.nearbyFrame; assert(f.pauseRow.shown and f.pauseRow.text.text:find('Paused: resting',1,true))")
test('The short pause after a loading screen keeps the plain status line',setup+"BuffTap.loadingUntil=GetTime()+5; refresh(); BuffTap:UpdateNearbyWindow(); local f=BuffTap.nearbyFrame; assert(not (f.pauseRow and f.pauseRow.shown))")
